CREATE OR REPLACE FUNCTION public.handle_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW."updatedAt" = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_conversation_creator_status()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.status = 'PENDING' AND EXISTS (
    SELECT 1 FROM public."Conversation" 
    WHERE id = NEW."conversationId" 
    AND ("createdBy" = NEW."userId" OR "createdBy" IS NULL)
  ) THEN
    NEW.status := 'ACCEPTED';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
